# -*- coding: utf-8 -*-
import ast
import json
import re
import fitz

cyrillic_pattern = re.compile(r'[\u0400-\u04FF]')

tajik_map = {
    'Љ': 'Ҷ', 'љ': 'ҷ',
    'Њ': 'Ҳ', 'њ': 'ҳ',
    'Ї': 'Ӣ', 'ї': 'ӣ',
    'Ќ': 'Қ', 'ќ': 'қ',
    'Ў': 'Ӯ', 'ў': 'ӯ',
    'Ѓ': 'Ғ', 'ѓ': 'ғ'
}

def clean_tajik(text):
    for k, v in tajik_map.items():
        text = text.replace(k, v)
    text = re.sub(r'(\w+)-\s*\n\s*(\w+)', r'\1\2', text)
    lines = [l.strip() for l in text.split('\n') if l.strip()]
    return ' '.join(lines)

def extract_pages(pdf_path, start_page, end_page, max_chars=1200):
    try:
        doc = fitz.open(pdf_path)
        combined = []
        s = max(0, start_page - 1)
        e = min(len(doc), end_page)
        for p in range(s, e):
            txt = clean_tajik(doc[p].get_text())
            txt = re.sub(r'^\d+\s*', '', txt)
            combined.append(txt)
            if sum(len(x) for x in combined) >= max_chars:
                break
        full = ' '.join(combined)
        full = re.sub(r'\s+', ' ', full).strip()
        return full[:max_chars].strip()
    except Exception as e:
        return ""

with open('assets/data/literature/poets.json', 'r', encoding='utf-8') as f:
    poets = json.load(f)

# Comprehensive mapping of Persian names for all 150 IDs
with open('tool/update_poets.py', 'r', encoding='utf-8') as f:
    content = f.read()

# Read only the two literal mappings needed from update_poets.py. Never execute
# the source file: it is a mutating tool and may be changed independently.
mapping_values = {}
tree = ast.parse(content, filename='tool/update_poets.py')
for node in tree.body:
    if not isinstance(node, ast.Assign):
        continue
    for target in node.targets:
        if isinstance(target, ast.Name) and target.id in {'CANONICAL_FA', 'TEXTBOOK_MAP'}:
            mapping_values[target.id] = ast.literal_eval(node.value)

if set(mapping_values) != {'CANONICAL_FA', 'TEXTBOOK_MAP'}:
    raise RuntimeError(
        'tool/update_poets.py must define literal CANONICAL_FA and TEXTBOOK_MAP mappings.'
    )
CANONICAL_FA = mapping_values['CANONICAL_FA']
TEXTBOOK_MAP = mapping_values['TEXTBOOK_MAP']

